<template>
  <!-- OBO-156: the badge is the way into "Herkunft des Wertes". A value that
       came from master data says so in words; the other sources keep their
       icon. Button semantics so it is reachable by keyboard as well — unless
       `interactive` is off (the module is switched off): then it is plain
       text that still says where the value came from. -->
  <span
    v-if="badgeConfig"
    :role="interactive ? 'button' : undefined"
    :tabindex="interactive ? 0 : undefined"
    data-test="extraction-source-badge"
    :aria-label="interactive ? badgeConfig.tooltip : undefined"
    :class="[
      'extraction-source-badge inline-flex items-center',
      interactive ? 'extraction-source-badge--interactive' : '',
      badgeConfig.colorClass,
      badgeConfig.masterData ? masterDataClass : '',
    ]"
    @click="onClick"
    @keydown="onKeydown"
  >
    <q-icon
      :name="badgeConfig.icon"
      :class="badgeConfig.colorClass"
      size="14px"
    />
    <span
      v-if="badgeConfig.masterData"
      data-test="extraction-source-badge-label"
      >{{ t('header_field_check_badge_master_data') }}</span
    >
    <q-tooltip>{{ badgeConfig.tooltip }}</q-tooltip>
  </span>
</template>

<script lang="ts">
import { defineComponent, computed, PropType } from 'vue';
import { useTranslate } from '@tolgee/vue';

export interface BadgeConfig {
  icon: string;
  colorClass: string;
  tooltip: string;
  /** The value came from master data: rendered as a text badge. */
  masterData?: boolean;
}

type ExtractionMethod = 'AI' | 'LEARNED' | 'MD' | 'FELLOW_KV2' | 'ELECTRONIC_DOCUMENT' | string;

export default defineComponent({
  name: 'ExtractionSourceBadge',
  props: {
    matchSource: { type: String, default: '' },
    lookupProvenance: { type: Object, default: null },
    original: { type: Object, default: null },
    currentValue: { type: String, default: '' },
    extractionMethod: {
      type: String as PropType<ExtractionMethod>,
      default: '',
    },
    /** false → no button role, no focus stop, no `open-origin`. */
    interactive: { type: Boolean, default: true },
  },
  emits: ['open-origin'],
  setup(props) {
    const { t } = useTranslate();
    const badgeConfig = computed((): BadgeConfig | null => {
      const dataset = props.lookupProvenance?.dataset ?? '';
      const original = props.original?.value ?? '';
      const hasOriginalValue = props.original &&
        Object.prototype.hasOwnProperty.call(props.original, 'value');
      if ((props.matchSource || props.lookupProvenance) && hasOriginalValue &&
          String(props.original.value) !== String(props.currentValue)) {
        const matchKind = props.lookupProvenance?.match_kind;
        const knownKind = ['exact', 'prefix', 'substring', 'alternate'].includes(matchKind);
        return {
          icon: 'mdi-swap-horizontal',
          colorClass: 'badge-replaced',
          masterData: true,
          tooltip: t.value('replaced_from_master_data_tooltip', {
            original, current: props.currentValue, dataset,
            kind: knownKind ? '; ' + t.value('match_kind_' + matchKind) : '',
          }),
        };
      }
      switch (props.matchSource) {
        case 'fuzzy_match':
          return {
            icon: 'mdi-database',
            colorClass: 'badge-database',
            tooltip: t.value('extraction_source_master_data'),
            masterData: true,
          };
        case 'lookup_exact':
          return {
            icon: 'mdi-database-check',
            colorClass: 'badge-database',
            masterData: true,
            tooltip: t.value('confirmed_by_master_data_tooltip', { dataset }),
          };
        case 'purchase_order':
          return {
            icon: 'mdi-file-link',
            colorClass: 'badge-database',
            masterData: true,
            tooltip: t.value('filled_from_purchase_order_tooltip', {
              original,
            }),
          };
      }
      if (!props.extractionMethod) {
        return null;
      }

      const method = props.extractionMethod.toUpperCase();

      switch (method) {
        case 'AI':
          return {
            icon: 'mdi-robot',
            colorClass: 'badge-ai',
            tooltip: t.value('header_field_check_source_tooltip_ai'),
          };
        case 'LEARNED':
          return {
            icon: 'mdi-school',
            colorClass: 'badge-learned',
            tooltip: t.value('header_field_check_source_tooltip_learned'),
          };
        case 'MD':
          return {
            icon: 'mdi-database',
            colorClass: 'badge-database',
            tooltip: t.value('extraction_source_master_data'),
            masterData: true,
          };
        case 'FELLOW_KV2':
          return {
            icon: 'mdi-database',
            colorClass: 'badge-database',
            tooltip: t.value('extraction_source_saved_rules'),
          };
        case 'ELECTRONIC_DOCUMENT':
          return {
            icon: 'mdi-file-document-outline',
            colorClass: 'badge-electronic',
            tooltip: t.value('header_field_check_source_tooltip_electronic'),
          };
        case 'CALCULATED':
          return {
            icon: 'mdi-calculator',
            colorClass: 'badge-calculated',
            tooltip: t.value('header_field_check_source_tooltip_calculated'),
          };
        default:
          return null;
      }
    });

    /** A replacement reads amber, a confirmation green — as the icon did. */
    const masterDataClass = computed(() =>
      [
        'gap-1 rounded border px-1.5 text-[11px] font-medium leading-4 text-foreground',
        badgeConfig.value?.colorClass === 'badge-replaced'
          ? 'border-warning/40 bg-warning/10'
          : 'border-success/40 bg-success/10',
      ].join(' '),
    );

    return {
      t,
      badgeConfig,
      masterDataClass,
    };
  },
  methods: {
    openOrigin() {
      this.$emit('open-origin');
    },
    onClick(event: MouseEvent) {
      // Plain text lets the click through to whatever sits around it.
      if (!this.interactive) return;
      event.stopPropagation();
      event.preventDefault();
      this.openOrigin();
    },
    onKeydown(event: KeyboardEvent) {
      if (!this.interactive) return;
      if (event.key !== 'Enter' && event.key !== ' ' && event.key !== 'Spacebar') return;
      // Space would scroll the panel, Enter would submit a surrounding form.
      event.preventDefault();
      event.stopPropagation();
      this.openOrigin();
    },
  },
});
</script>

<style lang="scss" scoped>
.extraction-source-badge {
  margin-left: 4px;
  vertical-align: middle;
  opacity: 0.8;

  &--interactive {
    cursor: pointer;
  }

  &--interactive:hover {
    opacity: 1;
  }

  &:focus-visible {
    opacity: 1;
    outline: 2px solid var(--ring);
    outline-offset: 1px;
    border-radius: 4px;
  }
}

// Colour the icon only: the class also sits on the root (the badge's
// public contract, see src/tests/unit/components) but must not tint the
// "aus Stammdaten" text label.
.q-icon.badge-ai {
  color: #9c27b0; // Purple for AI
}

.q-icon.badge-learned {
  color: #ff9800; // Orange for Learned
}

.q-icon.badge-database {
  color: #4caf50; // Green for Database/Rules
}

.q-icon.badge-replaced {
  color: #ffc107; // Amber for master-data replacements
}

.q-icon.badge-electronic {
  color: #2196f3; // Blue for Electronic Document
}

.q-icon.badge-calculated {
  color: #00897b; // Teal for Calculated fields
}
</style>
